parameters.source:
struct Params {
  amount: f32, // @default 1  0 is the input exactly, 1 is full FXAA.
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> params: Params;

const SPAN_MAX: f32 = 8.0;
const REDUCE_MUL: f32 = 0.125;
const REDUCE_MIN: f32 = 0.0078125;

fn tap(uv: vec2f) -> vec3f {
  return textureSampleLevel(inputTexture, inputSampler, uv, 0.0).rgb;
}

fn luma(c: vec3f) -> f32 {
  let t = max(c, vec3f(0.0)) / (vec3f(1.0) + max(c, vec3f(0.0)));
  return dot(t, vec3f(0.299, 0.587, 0.114));
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let px = 1.0 / vec2f(textureDimensions(inputTexture));
  let centre = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let m = centre.rgb;
  let lM = luma(m);
  let lNW = luma(tap(uv + vec2f(-1.0, -1.0) * px));
  let lNE = luma(tap(uv + vec2f(1.0, -1.0) * px));
  let lSW = luma(tap(uv + vec2f(-1.0, 1.0) * px));
  let lSE = luma(tap(uv + vec2f(1.0, 1.0) * px));
  let lMin = min(lM, min(min(lNW, lNE), min(lSW, lSE)));
  let lMax = max(lM, max(max(lNW, lNE), max(lSW, lSE)));

  var dir = vec2f(-((lNW + lNE) - (lSW + lSE)), (lNW + lSW) - (lNE + lSE));
  let reduce = max((lNW + lNE + lSW + lSE) * 0.25 * REDUCE_MUL, REDUCE_MIN);
  let rcpMin = 1.0 / (min(abs(dir.x), abs(dir.y)) + reduce);
  dir = clamp(dir * rcpMin, vec2f(-SPAN_MAX), vec2f(SPAN_MAX)) * px;

  let a = 0.5 * (tap(uv + dir * (1.0 / 3.0 - 0.5)) + tap(uv + dir * (2.0 / 3.0 - 0.5)));
  let b = a * 0.5 + 0.25 * (tap(uv - dir * 0.5) + tap(uv + dir * 0.5));
  let lB = luma(b);
  let smoothed = select(b, a, (lB < lMin) || (lB > lMax));
  // Alpha passes through untouched: an edge-smoothing pass has no business deciding coverage
  // (T1276 found the first version writing 1 over a plate that carried 0).
  return vec4f(mix(m, smoothed, params.amount), centre.a);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  threshold: f32,
  feather: f32,
  invert: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let s = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  /* Single-channel depth (r32float, T959) reads .r; colour maps read luma (T974's rule). */
  let d = select(dot(s.rgb, vec3f(0.2126, 0.7152, 0.0722)), s.r, s.g + s.b < 1e-6);
  var matte = smoothstep(params.threshold - params.feather, params.threshold + params.feather, d);
  matte = select(matte, 1.0 - matte, params.invert > 0.5);
  return vec4f(matte, matte, matte, matte);
}

parameters.kernel:
struct Params {
  unproject: f32,
  fov: f32,
  inverseDepth: f32,
  near: f32,
  far: f32,
  displace: f32,
}

fn decodeDepth(sample: f32, near: f32, far: f32, inverse: f32) -> f32 {
  /* inverse (ML disparity-like): bright = close; metres via the harmonic mix.
     linear: metres via the plain mix. Both span [near, far]. */
  let s = clamp(sample, 0.0, 1.0);
  let inv = 1.0 / mix(1.0 / far, 1.0 / near, s);
  let lin = mix(near, far, s);
  return select(lin, inv, inverse > 0.5);
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let near = max(ctx.params.near, 1.0e-3);
  let far = max(ctx.params.far, near + 1.0e-3);

  /* The generator may carry more capacity than the grid (a published resolution knob
     moves cols/rows under a fixed count): every index past the grid parks far outside
     the frustum and draws nothing. */
  let cells = ctx.dim.cols * ctx.dim.rows;
  if (ctx.index >= cells) {
    q.position = vec3f(0.0, -10000.0, 0.0);
    q.tint = vec4f(0.0);
    q.depthN = 0.0;
    return q;
  }

  /* The grid generator laid points across the clip square; that xy IS the depth map's
     uv in fieldAt's own convention — one mapping, shared. */
  let sample = fieldAt(vec3f(p.position.xy, 0.0));
  /* Single-channel maps (the depth node's r32float, T959) read .r; colour depth
     visualisations (turbo, viridis) read luma; grey maps agree under both. */
  let value = select(dot(sample.rgb, vec3f(0.2126, 0.7152, 0.0722)), sample.r, sample.g + sample.b < 1e-6);
  let metres = decodeDepth(value, near, far, ctx.params.inverseDepth);
  /* T973: the decoded depth rides its own attribute to the paint kernel — the heatmap
     is a second READOUT of the axis a 2D projection hides, not a decoration. 0 = near. */
  q.depthN = clamp((metres - near) / (far - near), 0.0, 1.0);

  if (ctx.params.unproject < 0.5) {
    /* HEIGHTFIELD: near pops toward the viewer, scaled by displace. */
    let relief = (1.0 - (metres - near) / (far - near)) * ctx.params.displace;
    q.position = vec3f(p.position.xy, relief);
    return q;
  }

  /* UNPROJECTION: ray through the pixel, scaled by metres, recentred about origin. */
  let dims = vec2f(textureDimensions(fieldTexture, 0));
  let aspect = dims.x / max(dims.y, 1.0);
  let ty = tan(ctx.params.fov * 0.00872664626);  /* radians(fov) / 2 */
  let ray = vec3f(p.position.x * ty * aspect, p.position.y * ty, -1.0);
  let mid = (near + far) * 0.5;
  let scaled = ray * metres * ctx.params.displace;
  q.position = vec3f(scaled.xy, scaled.z + mid * ctx.params.displace);
  return q;
}

struct Params {
  gain: f32,
  heat: f32,
}

/* T973 — a thermal readout of depth: near burns white-hot through orange, far cools
   through magenta into deep blue. Analytic, so no second texture is needed (a point
   kernel has ONE field input, and it is carrying the colour map). */
fn thermal(t: f32) -> vec3f {
  let n = clamp(1.0 - t, 0.0, 1.0);
  return vec3f(
    smoothstep(0.0, 0.45, n),
    smoothstep(0.5, 0.9, n) * 0.8,
    smoothstep(0.0, 0.2, n) * (1.0 - smoothstep(0.25, 0.6, n)) + smoothstep(0.85, 1.0, n),
  );
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let cols = max(ctx.dim.cols, 2u);
  let rows = max(ctx.dim.rows, 2u);
  if (ctx.index >= cols * rows) {
    q.tint = vec4f(0.0);
    return q;
  }
  let u = f32(ctx.dim.i) / f32(cols - 1u);
  let v = f32(ctx.dim.j) / f32(rows - 1u);
  /* fieldAt speaks clip coordinates; the grid generator's layout inverted nothing, so
     the same mapping the carve kernel rode puts the colour texel under its point. */
  let colour = fieldAt(vec3f(u * 2.0 - 1.0, v * 2.0 - 1.0, 0.0));
  /* T973: photographic at heat 0, thermal at 1 — and the middle is the point: the
     source's own colour with depth bleeding through, one knob rather than a mode. */
  let blended = mix(colour.rgb, thermal(p.depthN), clamp(ctx.params.heat, 0.0, 1.0));
  /* §T977 follow-up: the field's ALPHA is honoured as COVERAGE, premultiplied — the
     colour carries the coverage, the scene renderer's own additive convention, and the
     same rule this kernel already applies at its two parked exits (tint = vec4f(0.0)).
     A masked colour map (DepthCut) now actually darkens the motes it cut. CLAMPED,
     because coverage is [0, 1] by meaning: an additive composite upstream SUMS alphas
     (measured - a lit disc over an opaque bed reads a = 2), and honouring that literally
     would double the rgb of every such point. With the clamp, any map that is
     opaque-or-over is bit-identical to the pre-fix output. */
  let cover = clamp(colour.a, 0.0, 1.0);
  q.tint = vec4f(blended * ctx.params.gain * cover, cover);
  return q;
}

parameters.source:
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  grid: vec2f,
  amount: f32,
  rate: f32,
  seed: f32,
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

// @use grid
/*
 * Integer avalanche (the "lowbias32" family), and INTEGER on purpose: a float hash built
 * on fract(sin(x)) is a different number on every driver, and §V44's sibling promise — a
 * seeded look replays identically — would be a per-machine accident. u32 shifts and
 * multiplies are exact everywhere WGSL runs.
 */
fn hashU(value: u32) -> f32 {
  var x = value;
  x = x ^ (x >> 16u);
  x = x * 0x7feb352du;
  x = x ^ (x >> 15u);
  x = x * 0x846ca68bu;
  x = x ^ (x >> 16u);
  return f32(x & 0x00ffffffu) / 16777216.0;
}

/* Sample this cell, displaced along x and WRAPPED INSIDE IT — the one rule every
   degradation obeys, because a tear or a fringe that crossed a seam would read as a
   broken TILING rather than as a broken monitor. The +4.0 is there because fract() of a
   negative is not the wrap we want and every shove is signed. */
fn tap(cell: GridCell, dx: f32) -> vec4f {
  let local = vec2f(fract(cell.local.x + dx + 4.0), cell.local.y);
  return textureSampleLevel(inputTexture, inputSampler, cell.origin + (local * cell.size), 0.0);
}

/*
 * A BURST SLOT — the envelope, and the whole of what changed in pass 3.
 *
 * Each slot is an independent, deterministic pulse train on ONE cell: a period in frames,
 * a lifetime of a few frames, and a per-cycle roll that decides whether this cycle fires
 * at all. A cell's phase inside its own slot is hashed from its index, so thirty-six cells
 * on the same slot are thirty-six unsynchronised trains rather than one flashbulb.
 *
 * Returns the burst's AGE in frames, or -1 when the slot is quiet.
 *
 * The periods are co-prime frame counts, so two slots on one cell realign only every
 * few hundred frames and three of them effectively never. That is what "multiple random
 * glitches" needs and a single tick cannot give: several short events in flight at
 * different phases.
 */
fn slot(index: u32, seed: u32, salt: u32, period: f32, life: f32, chance: f32, frame: f32) -> f32 {
  /* Per-cell phase, so the wall does not pulse in unison. */
  let shifted = frame + (hashU((index * 7919u) ^ salt) * period);
  let cycle = floor(shifted / period);
  let age = shifted - (cycle * period);
  if (age >= life) { return -1.0; }
  if (hashU((index * 1013u) + (seed * 6151u) + salt + (u32(cycle) * 3571u)) >= chance) { return -1.0; }
  return age;
}

/* Co-prime frame periods. Nothing here shares a factor with anything else here. */
const TEAR_A: f32 = 17.0;
const TEAR_B: f32 = 23.0;
const TEAR_C: f32 = 31.0;
const SNOW_A: f32 = 13.0;
const SNOW_B: f32 = 19.0;
const DROP_P: f32 = 47.0;

/*
 * LIFETIMES, in frames, and they are the owner's note made numeric. A tear that lasts two
 * or three frames at 60 fps is 33-50 ms — a flicker you catch rather than a state you
 * watch. Snow is shorter still. A DROPOUT is the exception and holds for a fifth of a
 * second, because it is not damage: it is the cell briefly becoming a different picture,
 * and a two-frame version of that reads as a dropped frame rather than as an idea.
 */
const TEAR_LIFE: f32 = 3.0;
/*
 * FOUR, and the previous value was the owner's whole complaint: "the static noise in the
 * glitch animation is like just ONE FRAME — that looks not well blended". It literally
 * was. The second snow train ran at SNOW_LIFE - 1, so at SNOW_LIFE = 2 it was a
 * single-frame flash — and a single frame does not read as texture, it reads as a POP.
 * The tears were given 2-3 frames for exactly this reason and the static never got the
 * same treatment. At 4 and 3 it lasts long enough to be seen as grain.
 *
 * SNOW_SHARE comes down with it (0.35 -> 0.18) so the DUTY CYCLE barely moves: life/period
 * x chance was (2/13 + 1/19) x 0.35 = 0.073 and is now (4/13 + 3/19) x 0.18 = 0.084. A
 * longer event that fires proportionally less often is the whole trade; leaving the share
 * alone would have doubled the amount of static on the wall.
 */
const SNOW_LIFE: f32 = 4.0;
const DROP_LIFE: f32 = 12.0;

/* Relative rarity. A tear is the wall's ordinary weather; snow is an interruption; a
   dropout is an EVENT, because it changes what the cell is a picture OF. */
/*
 * How deep the grain modulates what is already there. Bounded above by construction (see
 * the SNOW branch), so this is a texture depth and not a clipping risk.
 *
 * 0.30, down from 0.45, on the owner's "too bright" a second time — and it is the
 * SECOND half of that repair, not the whole of it: the brightening was the silhouette
 * term (see the SNOW branch), and dropping the depth without deleting that would have
 * been another dimmer wrong picture.
 *
 * It stays modest for the RECOLORIZER's sake too: a Lookup turns luminance into a palette
 * position, so a deep luminance grain walks the whole palette between neighbouring texels
 * and monochrome noise arrives as multicoloured confetti (§V853). Measured after this
 * change, chroma across a snowing cell moves less than the clean cell's, so the grain is
 * staying inside one region of the palette.
 */
const SNOW_DEPTH: f32 = 0.3;

const TEAR_SHARE: f32 = 0.55;
const SNOW_SHARE: f32 = 0.18;
const DROP_SHARE: f32 = 0.30;

fn luma(rgb: vec3f) -> f32 {
  return dot(rgb, vec3f(0.2126, 0.7152, 0.0722));
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let dims = vec2f(textureDimensions(inputTexture));
  let texel = vec2i(clamp(uv * dims, vec2f(0.0), dims - vec2f(1.0)));
  let here = textureLoad(inputTexture, texel, 0);
  if (params.amount <= 0.0) { return vec4f(here.rgb, 1.0); }

  let cell = gridCellAt(uv, params.grid);
  let index = u32(cell.index);
  let seed = u32(clamp(params.seed, 0.0, 65535.0));
  /* FRAMES, not seconds: an event two frames long has to be counted in the unit it is two
     of. absFrame is the deterministic frame count the transport supplies (§V44) — never a
     wall clock. Rate stretches or compresses every period together, so the whole wall
     speeds up as one instrument. max(0.25) keeps the trains turning at Rate 0. */
  let frame = frameU.absFrame * max(0.25, params.rate);
  let tick = u32(frame);

  /* THE AUDIO GATE: this cell's own centre texel. Bright cells are dealt in first, so a
     source that responds to the music makes the damage chase the beat across the wall. */
  let middle = vec2i(clamp((cell.origin + (0.5 * cell.size)) * dims, vec2f(0.0), dims - vec2f(1.0)));
  let lit = clamp(luma(textureLoad(inputTexture, middle, 0).rgb), 0.0, 1.0);
  let base = clamp(params.amount * (0.2 + (1.8 * lit)), 0.0, 1.0);

  /* THREE TEAR TRAINS, TWO SNOW TRAINS, ONE DROPOUT — all independent, all per cell. */
  let tearAge = max(
    slot(index, seed, 101u, TEAR_A, TEAR_LIFE, base * TEAR_SHARE, frame),
    max(
      slot(index, seed, 211u, TEAR_B, TEAR_LIFE - 1.0, base * TEAR_SHARE, frame),
      slot(index, seed, 307u, TEAR_C, TEAR_LIFE, base * TEAR_SHARE, frame)));
  let snowAge = max(
    slot(index, seed, 409u, SNOW_A, SNOW_LIFE, base * SNOW_SHARE, frame),
    slot(index, seed, 521u, SNOW_B, SNOW_LIFE - 1.0, base * SNOW_SHARE, frame));
  let dropAge = slot(index, seed, 631u, DROP_P, DROP_LIFE, base * DROP_SHARE, frame);

  /* EXCLUSIVE, rarest first. One thing per cell per frame, on purpose: at 6x6 a cell is a
     couple of thousand pixels and a tear under snow is mud. The variety is in WHICH cells
     and WHICH kind, and it is asserted. */
  if (dropAge >= 0.0) {
    /* DROPOUT — the background falls away. Alpha arrived here as the MATTE, packed into
       the picture before the ring (see the component's pack node), so it has been delayed
       by exactly the same number of frames as the colour it belongs to: a cell holding a
       moment from a second ago drops the background of THAT moment, not of now. */
    return vec4f(here.rgb * clamp(here.a, 0.0, 1.0), 1.0);
  }

  if (snowAge >= 0.0) {
    /*
     * SNOW — and this branch has been rebuilt twice, both times at the cause.
     *
     * WHAT IT LOOKED LIKE WHEN IT WAS WRONG: the owner photographed a two-cell block of
     * full-intensity multicoloured confetti with none of the picture left in it. Three
     * separate faults, none of them a level:
     *
     *  1. IT REPLACED THE PICTURE. mix(silhouette, grain, 0.65) writes a value that owes
     *     almost nothing to what was there, so a cell stopped being a picture. Static has
     *     to RIDE the image — that is the difference between static and a dropout, and
     *     this component already has a dropout.
     *  2. IT CAME OUT CHROMATIC, and not because the grain was. The grain is monochrome
     *     here and always was; the CONFETTI is made downstream, by the recolorizer. A
     *     Lookup maps luminance to a palette position, so a full-swing luminance grain
     *     walks the whole palette between adjacent texels and monochrome noise arrives on
     *     screen as per-pixel colour garbage. The fix is at this end: keep the luminance
     *     excursion small enough that the palette index barely moves, and the same noise
     *     reads as grain instead.
     *  3. IT WAS TOO BIG AND TOO SOLID. A whole cell of it is a rectangle, and a rectangle
     *     is a graphic, not a fault. It is banded now — a few scanline bands per burst —
     *     so it reads as a monitor breaking up rather than as a filled shape.
     *
     * MULTIPLICATIVE, AND HIGHLIGHT-PROTECTED (§V833/§V838). The output is bounded by
     * crushed * (1 + SNOW_DEPTH), and the weight is already ~0 wherever the pixel is
     * bright — so it cannot reach the clip BY CONSTRUCTION, not by tuning. The owner's
     * "it oversteers, overflows" was literal: it was clipping to flat white, and a lower
     * amount would only have made a dimmer wrong picture. The gate asserts the property
     * rather than the number: zero pixels at 1.0 anywhere in a snowing wall.
     *
     */
    let grain = hashU((u32(texel.x) * 73856093u) ^ (u32(texel.y) * 19349663u) ^ (tick * 83492791u) ^ seed);
    /* SCANLINE BANDS, not the whole cell: only some of them break up on a given burst. */
    let bandCount = 5.0 + floor(hashU((index * 5501u) + (tick * 79u) + seed) * 7.0);
    let bandIndex = u32(floor(cell.local.y * bandCount));
    let banded = select(0.35, 1.0, hashU((bandIndex * 2237u) + (index * 91u) + (tick * 397u) + seed) < 0.45);
    /*
     * GRAIN ON THE PICTURE. Two things were removed here, and BOTH were measured before
     * being touched, because "too bright" had already survived one repair.
     *
     * 1. THE SILHOUETTE LIFT. mix(base, step(0.35, base), 0.25) raised every pixel above
     *    the threshold by 0.25 x (1 - base) — a flat +0.10 on a bright cell before any
     *    grain existed. Measured: a snowing cell's mean read 0.7315 against the clean
     *    cell's 0.6853. It was never snow's job; Crush is a published knob with a level
     *    node behind it, and a second hidden discontinuous threshold inside one
     *    degradation is how a control surface stops being trustworthy. Deleted, not
     *    reduced.
     *
     * 2. THE DESATURATION. Writing luma into all three channels made the cell a GREY
     *    PATCH — the owner's "out of place" — and it also made it read brighter for a
     *    reason no amount of level-tweaking would have fixed: the sink's transfer is
     *    concave, so luma-of-encoded is not encode-of-luma, and a monochrome cell at
     *    IDENTICAL linear luminance measures 0.7042 encoded against a colour cell's
     *    0.6853. The picture was not brighter; it had stopped being the picture. So the
     *    grain now rides the colour instead of replacing it, which is what film grain is.
     *
     * §V853 was the third suspect and the same measurement CLEARED it: chroma after the
     * palette went 0.546 -> 0.540, DOWN. The lookup was not amplifying grain into a
     * dimension it lacked.
     *
     * What is left is a symmetric multiplicative modulation, so its expected shift in
     * LINEAR luminance is zero by construction — measured at 0.4841 -> 0.4842, and that is
     * what the gate asserts. Every pixel of a snowing cell is therefore a positive SCALING
     * of the pixel that was there, which is also how the gate tells snow from a tear (a
     * tear moves pixels) and from a dropout (which zeroes them).
     */
    /*
     * The weight is keyed on the PEAK CHANNEL, not on luminance, and that is a correctness
     * fix rather than a nicety: clipping happens per channel, so protection has to be
     * measured per channel. Keyed on luma, a pixel at luma 0.5 could still carry a red of
     * 0.95, get the full grain because its luma looked safe, and clamp — measured, that
     * pushed 7005 pixels onto the sink's ceiling against a clean frame's 3456. Keyed on
     * the peak, the product peak x (1 + SNOW_DEPTH x weight(peak)) tops out around 0.9
     * across the whole range, so nothing can reach the clamp at all.
     */
    let peak = max(here.r, max(here.g, here.b));
    let weight = (1.0 - smoothstep(0.30, 0.92, peak)) * banded;
    let value = here.rgb * (1.0 + (SNOW_DEPTH * weight * ((grain * 2.0) - 1.0)));
    return vec4f(value, 1.0);
  }

  if (tearAge >= 0.0) {
    /*
     * TEAR — bands shove sideways with an RGB fringe riding the same displacement.
     *
     * PASS 3 CHANGED THE ENVELOPE, not the mechanism. Every one of these numbers now
     * re-deals on the FRAME rather than being held for a whole tick: a burst is two or
     * three frames long and the bands jump within it, which is what a glitch looks like.
     * Held for a tick — the pass-2 design — it was one clean state sitting there for half
     * a second, and the owner's verdict was that it read as slow and simplified.
     */
    let strength = params.amount * (0.35 + (0.65 * hashU((index * 337u) + (tick * 61u) + seed)));
    let bands = 4.0 + floor(hashU((index * 977u) + (tick * 131u) + seed) * 12.0);
    let band = u32(floor(cell.local.y * bands));
    let shove = (hashU((band * 1471u) + (index * 29u) + (tick * 523u) + seed) - 0.5) * 0.7 * strength;
    let split = 0.06 * strength;
    let mid = tap(cell, shove);
    let red = tap(cell, shove + split);
    let blue = tap(cell, shove - split);
    return vec4f(red.r, mid.g, blue.b, 1.0);
  }

  return vec4f(here.rgb, 1.0);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  grid: vec2f,
  mode: f32,
  rate: f32,
  seed: f32,
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

// @use grid
/*
 * Integer avalanche (the "lowbias32" family), and INTEGER on purpose: a float hash built
 * on fract(sin(x)) is a different number on every driver, and §V44's sibling promise — a
 * seeded look replays identically — would be a per-machine accident. u32 shifts and
 * multiplies are exact everywhere WGSL runs.
 */
fn hashU(value: u32) -> f32 {
  var x = value;
  x = x ^ (x >> 16u);
  x = x * 0x7feb352du;
  x = x ^ (x >> 15u);
  x = x * 0x846ca68bu;
  x = x ^ (x >> 16u);
  return f32(x & 0x00ffffffu) / 16777216.0;
}

/* Sample this cell, displaced along x and WRAPPED INSIDE IT — the one rule every
   degradation obeys, because a tear or a fringe that crossed a seam would read as a
   broken TILING rather than as a broken monitor. The +4.0 is there because fract() of a
   negative is not the wrap we want and every shove is signed. */
fn tap(cell: GridCell, dx: f32) -> vec4f {
  let local = vec2f(fract(cell.local.x + dx + 4.0), cell.local.y);
  return textureSampleLevel(inputTexture, inputSampler, cell.origin + (local * cell.size), 0.0);
}

const SHOT_ANGLES: f32 = 4.0;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let cell = gridCellAt(uv, params.grid);
  let index = cell.index;
  let seed = u32(clamp(params.seed, 0.0, 65535.0));
  let mode = i32(params.mode + 0.5);

  var delay = 0.0;
  if (mode == 1) {
    /* ORDERED — the cascade. Reading order, oldest at the bottom right. */
    delay = index / cell.last;
  } else if (mode == 2) {
    /* RANDOM — every cell its own moment, held. Seeded, so it is a LOOK, not noise. */
    delay = hashU((u32(index) * 1973u) + (seed * 9277u));
  } else if (mode == 3) {
    /*
     * SWEEP — the owner's "freeze that wanders through".
     *
     * Each cell's delay RAMPS, so it looks one frame further back every frame: at
     * Rate 1.0 (with Spread 1) that is exactly one ring-frame per rendered frame, and
     * the cell holds STILL while the world moves on. The phase offset per cell means
     * they wrap at different times, so the wall refreshes as a rolling wave rather than
     * all at once. Below 1.0 the held frame plays in slow motion; above it, backwards.
     */
    delay = fract((index / cell.count) + (frameU.absTime * params.rate));
  } else if (mode == 4) {
    /*
     * SHOTS — several angles of one scene, cut on a clock.
     *
     * Cells are dealt to SHOT_ANGLES groups by the seeded hash and every group holds one
     * rung of the delay ladder; the ladder rotates one rung per tick, so the whole wall
     * re-cuts at once and then holds. Distinct from RANDOM, which never re-cuts, and from
     * SWEEP, which never holds a whole group together.
     */
    let angle = floor(hashU((u32(index) * 6151u) + (seed * 1543u)) * SHOT_ANGLES);
    let turn = floor(frameU.absTime * max(0.0, params.rate));
    delay = ((angle + turn) % SHOT_ANGLES) / (SHOT_ANGLES - 1.0);
  }
  /* mode 0 — UNIFORM — falls through at 0.0: every cell reads the newest recorded frame,
     so the wall is the plain tiling and the scan is a no-op you can see (§V147's shape). */

  return vec4f(delay, delay, delay, 1.0);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  grid: vec2f,
  amount: f32,
  rate: f32,
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

// @use grid
/*
 * Integer avalanche (the "lowbias32" family), and INTEGER on purpose: a float hash built
 * on fract(sin(x)) is a different number on every driver, and §V44's sibling promise — a
 * seeded look replays identically — would be a per-machine accident. u32 shifts and
 * multiplies are exact everywhere WGSL runs.
 */
fn hashU(value: u32) -> f32 {
  var x = value;
  x = x ^ (x >> 16u);
  x = x * 0x7feb352du;
  x = x ^ (x >> 15u);
  x = x * 0x846ca68bu;
  x = x ^ (x >> 16u);
  return f32(x & 0x00ffffffu) / 16777216.0;
}

/* Sample this cell, displaced along x and WRAPPED INSIDE IT — the one rule every
   degradation obeys, because a tear or a fringe that crossed a seam would read as a
   broken TILING rather than as a broken monitor. The +4.0 is there because fract() of a
   negative is not the wrap we want and every shove is signed. */
fn tap(cell: GridCell, dx: f32) -> vec4f {
  let local = vec2f(fract(cell.local.x + dx + 4.0), cell.local.y);
  return textureSampleLevel(inputTexture, inputSampler, cell.origin + (local * cell.size), 0.0);
}

/* Slow against everything else on the wall: one pass every ~7.7 s at Rate 1. The whole
   point of a sweep is that you wait for it. */
const SWEEP_HZ: f32 = 0.13;
/* Half-width, in frame widths. 0.22 puts the band across about two cells of a 6-wide wall
   — wide enough to read as a front travelling, narrow enough to leave somewhere clean. */
const SWEEP_HALF_WIDTH: f32 = 0.22;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let dims = vec2f(textureDimensions(inputTexture));
  let texel = vec2i(clamp(uv * dims, vec2f(0.0), dims - vec2f(1.0)));
  let here = textureLoad(inputTexture, texel, 0);
  if (params.amount <= 0.0) { return here; }

  let centre = fract(frameU.absTime * SWEEP_HZ * max(0.05, params.rate));
  let distance = abs(uv.x - centre);
  /* Wrapped, so the band leaves the right edge and arrives at the left. */
  let wrapped = min(distance, 1.0 - distance);
  let band = 1.0 - smoothstep(0.0, SWEEP_HALF_WIDTH, wrapped);
  if (band <= 0.0) { return here; }

  let cell = gridCellAt(uv, params.grid);
  /* 0.12 of a CELL width at full Chroma, measured against the picture rather than
     chosen: at 0.05 the fringe was under two texels on a 6-wide wall and did not read. */
  let shift = 0.12 * params.amount * band;
  let red = tap(cell, shift);
  let blue = tap(cell, -shift);
  return vec4f(red.r, here.g, blue.b, here.a);
}

parameters.kernel:
struct Params {
  height: f32,      // @default 4  Wall height in metres. PLACEHOLDER: real dimensions are not confirmed.
  frontWidth: f32,  // @default 4.8  Middle wall width in metres: 1296 of the file's 1944 px, square pixels assumed.
  sideDepth: f32,   // @default 1.2  Length of each side wall in metres: 324 of the file's 1944 px.
  fold: f32,        // @default 90  Degrees each side wall turns from flat. +90 folds back (upstage), -90 folds forward (toward the house), 0 is the flat strip.
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  // Where this column sits across the FILE: 0 is its left edge, 1 its right.
  // The grid's column is also the uv the video is sampled by, so the picture and the fold share one coordinate.
  let u = f32(ctx.dim.i) / f32(max(ctx.dim.cols, 2u) - 1u);
  let v = f32(ctx.dim.j) / f32(max(ctx.dim.rows, 2u) - 1u);
  // The seams: 1/6 and 5/6 of the width (x 324 and 1620 of 1944). Keep the grid's columns a multiple of 6, plus 1, so a column lands on each.
  let past = max(max(1.0 / 6.0 - u, u - 5.0 / 6.0), 0.0) * 6.0;  // 0 on the middle wall, 0..1 along a side wall
  let along = past * ctx.params.sideDepth;
  let side = sign(u - 0.5);
  let middle = clamp((u - 1.0 / 6.0) * 1.5, 0.0, 1.0);
  let half = ctx.params.frontWidth * 0.5;
  let a = radians(ctx.params.fold);
  q.position = vec3f(
    mix(-half, half, middle) + side * cos(a) * along,
    // Row 0 is the TOP of the wall: the picture's first row is its top row, and the grid's row is the uv.
    (1.0 - v) * ctx.params.height,
    -sin(a) * along,
  );
  return q;
}
